--
-- Table structure for table `modules`
--

CREATE TABLE `modules` (
  `module_id` int(100) NOT NULL,
  `title` varchar(100) NOT NULL,
  `description` text NOT NULL,
  `image_path` varchar(100) NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `rewards` text DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

--
-- Dumping data for table `modules`
--

INSERT INTO `modules` (`module_id`, `title`, `description`, `image_path`, `created_at`, `updated_at`, `rewards`) VALUES
(1, 'Introduction to Urban Agriculture', 'In this module, you’ll learn about the fundamentals of urban agriculture, including its definition, historical development, and key benefits. You will also explore how farming within cities supports food security, sustainability, and community well-being.', '../html/moduleimages/module_1783757351_7710.jpg', '2025-09-16 06:58:21', '2026-07-11 08:09:11', 'Free seeds: Kangkong and Pechay\r\nFree Nursery Pots'),
(2, 'Planning and Designing Urban Agriculture Systems', 'Urban agriculture systems must be carefully planned and designed to maximize the use of\r\navailable resources, ensure sustainability, and adapt to urban constraints. This module provides a\r\ndetailed guide to site assessment, system designs, and resource management.', '../html/moduleimages/module_1767852055_7385.jpg', '2025-09-16 10:31:50', '2026-01-29 02:35:09', 'Free seeds: Okra and Alugbati'),
(3, 'Techniques and Practices in Urban Agriculture', 'This module focuses on various techniques and practices essential for successful urban\r\nagriculture. It covers soil-based farming, soilless farming techniques (hydroponics and\r\naeroponics), and the importance of composting and resource recycling in urban settings.', '../html/moduleimages/module_1767852063_4288.jpg', '2025-09-17 02:51:30', '2026-01-29 02:35:47', 'Free seeds: Sitao and Upo'),
(4, 'Pest and Disease Management in Urban Farming', 'Effective pest and disease management is crucial for urban agriculture, where limited space and proximity to homes and communities require sustainable and environmentally friendly approaches. Integrated Pest Management (IPM) integrates biological, cultural, mechanical, and chemical controls to manage pests and diseases without harming the environment or human health.', '../html/moduleimages/module_1767852071_4463.jpg', '2025-09-17 03:29:05', '2026-01-29 02:36:06', 'Free seeds: Eggplant and Saluyot'),
(5, 'Crop Selection and Calendar Planning (Baguio City Focus)', 'In urban agriculture, selecting the right crops and creating an efficient seasonal crop calendar are essential for maximizing yields, meeting market demands, and ensuring the sustainability of farming systems. Baguio City, with its distinct climate and terrain, presents unique challenges and opportunities for crop selection. This module provides a comprehensive approach to understanding these factors and creating an effective crop calendar tailored to Baguio City\'s conditions.', '../html/moduleimages/module_1767852088_2399.jpg', '2025-09-17 03:48:32', '2026-01-29 02:37:12', 'Free seeds: Tomato\r\nFree Nursery Pots'),
(21, 'Organic Fertilizer for Sustainable Urban Farming', 'Organic fertilizer is an important part of sustainable urban farming because it provides nutrients to plants while making use of naturally occurring organic materials. This module introduces learners to organic fertilizers, their different types, methods of production, proper application, and environmental importance. Learners will also explore how household and garden waste can be transformed into useful materials for growing plants.', '../images/modules/module_1786186563_6a770b436701c.jpg', '2026-08-08 06:03:34', '2026-08-08 10:56:03', 'Organic Fertilizer and Onion Leeks Seeds'),
(22, 'Applying Organic Fertilizer for Healthy Plant Growth', 'This module introduces learners to the proper application of organic fertilizer in urban farming. It covers when, where, and how to apply fertilizer, how to determine appropriate amounts, and the importance of considering plant and soil needs. Learners will also explore common fertilizer application methods and responsible practices that help prevent nutrient waste, plant damage, and environmental pollution. Through practical examples and activities, learners will develop the knowledge and skills needed to apply organic fertilizer safely and effectively in an urban garden.', '../images/modules/module_1786336578_6a7955423077f.jpg', '2026-08-10 00:23:08', '2026-08-10 04:36:18', 'Organic Fertilizer and  Pechay - Shingkang Seeds'),
(23, 'Soil Preparation for Urban Gardening', 'This module introduces learners to the importance of preparing healthy soil for urban gardening. It covers the basic components and characteristics of soil, how to assess soil condition, methods for preparing soil before planting, suitable growing media for containers, and practices for maintaining healthy soil. Through practical examples and activities, learners will develop the knowledge needed to create suitable growing conditions for plants in urban gardens.', '../images/modules/module_1786336784_6a795610c549c.jpg', '2026-08-10 04:39:44', '2026-08-10 04:39:44', ''),
(24, 'Seed Selection and Seed Starting', 'This module introduces learners to the basics of selecting quality seeds and starting healthy seedlings for urban gardening. It covers how to choose suitable seeds, understand seed labels and requirements, prepare containers and growing media, sow seeds correctly, and care for seedlings during their early growth. Through practical examples and activities, learners will develop the knowledge and skills needed to successfully start plants from seeds in containers, garden beds, and other urban growing spaces.', '../images/modules/module_1786339632_6a796130ecdc0.jpg', '2026-08-10 05:27:12', '2026-08-10 05:27:33', ''),
(25, 'Harvesting and Post-Harvest Handling', 'This module introduces learners to the proper methods of harvesting and handling crops in an urban garden. It covers how to identify crop maturity, choose appropriate harvesting techniques, handle harvested produce safely, and properly clean, sort, store, and transport crops. Learners will also explore ways to reduce post-harvest losses and food waste while maintaining the quality and freshness of harvested produce.', '../images/modules/module_1786348252_6a7982dc8a748.jpg', '2026-08-10 07:50:52', '2026-08-10 07:50:52', '');

